package vault

import (
	"encoding/hex"
	"strings"
	"testing"

	"github.com/LeJamon/go-xrpl/amendment"
	"github.com/LeJamon/go-xrpl/internal/tx"
)

func vaultGoldenRules() []struct {
	name  string
	rules *amendment.Rules
} {
	return []struct {
		name  string
		rules *amendment.Rules
	}{
		{name: "nil", rules: nil},
		{name: "legacy", rules: amendment.NewRules([][32]byte{amendment.FeatureSingleAssetVault})},
		{name: "cleanup320", rules: amendment.NewRules([][32]byte{amendment.FeatureSingleAssetVault, amendment.FeatureFixCleanup3_2_0})},
		{name: "cleanup330", rules: amendment.NewRules([][32]byte{amendment.FeatureSingleAssetVault, amendment.FeatureFixCleanup3_2_0, amendment.FeatureFixCleanup3_3_0})},
	}
}

func vaultGoldenCases() []struct {
	name string
	data *vaultData
} {
	var owner, account [20]byte
	for i := range owner {
		owner[i] = byte(i + 1)
		account[i] = byte(i + 21)
	}
	var shareID, mptID [24]byte
	var txnID [32]byte
	for i := range shareID {
		shareID[i] = byte(0xA0 + i)
		mptID[i] = byte(0x10 + i)
	}
	for i := range txnID {
		txnID[i] = byte(0xC0 + i)
	}
	sub, red := uint32(1000), uint32(2000)
	base := func() *vaultData {
		return &vaultData{
			Owner:             owner,
			Account:           account,
			Sequence:          42,
			OwnerNode:         3,
			ShareMPTID:        shareID,
			Asset:             tx.Asset{Currency: "XRP"},
			WithdrawalPolicy:  VaultStrategyFirstComeFirstServe,
			PreviousTxnID:     txnID,
			PreviousTxnLgrSeq: 77,
		}
	}
	issuer := "rPT1Sjq2YGrBMTttX4GZHjKu9dyfzbpAYe"

	minimal := base()
	minimal.Sequence, minimal.OwnerNode, minimal.WithdrawalPolicy = 0, 0, 0
	minimal.ShareMPTID, minimal.PreviousTxnID, minimal.PreviousTxnLgrSeq = [24]byte{}, [32]byte{}, 0

	xrpInts := base()
	xrpInts.AssetsTotal, xrpInts.AssetsAvailable, xrpInts.AssetsMaximum, xrpInts.LossUnrealized = "1000000", "999999", "100000000000", "1"

	iou := base()
	iou.Asset = tx.Asset{Currency: "USD", Issuer: issuer}
	iou.Flags, iou.Scale, iou.LEVersion, iou.VaultKind = 1, 6, 1, 1
	iou.SubscriptionDate, iou.RedemptionDate = &sub, &red
	iou.Data, iou.DataPresent = "deadbeef", true
	iou.AssetsTotal, iou.AssetsAvailable, iou.AssetsMaximum, iou.LossUnrealized = "1234.5678", "0.000001", "1e30", "0.5"

	emptyData := base()
	emptyData.DataPresent = true
	emptyData.AssetsTotal, emptyData.AssetsAvailable, emptyData.AssetsMaximum, emptyData.LossUnrealized = "0", "0", "0", "0"

	mpt := base()
	mpt.AssetIsMPT, mpt.AssetMPTID = true, mptID
	mpt.AssetsTotal, mpt.AssetsAvailable, mpt.AssetsMaximum = "9223372036854775807", "9223372036854775807e0", "9223372036854775806"

	large := base()
	large.Asset = tx.Asset{Currency: "EUR", Issuer: issuer}
	large.AssetsTotal, large.AssetsAvailable, large.AssetsMaximum, large.LossUnrealized = "9999999999999999999e-5", "12345678901234567891", "9223372036854775808", "18446744073709551615e10"

	small := base()
	small.Asset = tx.Asset{Currency: "EUR", Issuer: issuer}
	small.AssetsTotal, small.AssetsAvailable, small.AssetsMaximum, small.LossUnrealized = "1e-80", "1e-96", "12345678901234567e-60", "3.333333333333333333"

	negative := base()
	negative.Asset = tx.Asset{Currency: "EUR", Issuer: issuer}
	negative.AssetsTotal, negative.AssetsAvailable, negative.AssetsMaximum, negative.LossUnrealized = "-1", "-123.456", "-9223372036854775807", "-1e-40"

	return []struct {
		name string
		data *vaultData
	}{
		{name: "minimal", data: minimal},
		{name: "xrp_integers", data: xrpInts},
		{name: "iou_all_optional", data: iou},
		{name: "explicit_zero_numbers_empty_data", data: emptyData},
		{name: "mpt_max_int64", data: mpt},
		{name: "large_mantissas_rounding", data: large},
		{name: "small_mantissas", data: small},
		{name: "negative_numbers", data: negative},
	}
}

// TestVaultSerializationGolden pins the exact bytes of representative Vault
// entries under every large Number mantissa scale; Vault entries only exist
// once SingleAssetVault or LendingProtocol installs one.
func TestVaultSerializationGolden(t *testing.T) {
	want := map[string]string{
		"minimal/nil":                                 "",
		"minimal/small":                               "",
		"minimal/legacy":                              "",
		"minimal/cleanup320":                          "",
		"minimal/cleanup330":                          "",
		"xrp_integers/nil":                            "",
		"xrp_integers/small":                          "",
		"xrp_integers/legacy":                         "",
		"xrp_integers/cleanup320":                     "",
		"xrp_integers/cleanup330":                     "",
		"iou_all_optional/nil":                        "",
		"iou_all_optional/small":                      "",
		"iou_all_optional/legacy":                     "",
		"iou_all_optional/cleanup320":                 "",
		"iou_all_optional/cleanup330":                 "",
		"explicit_zero_numbers_empty_data/nil":        "",
		"explicit_zero_numbers_empty_data/small":      "",
		"explicit_zero_numbers_empty_data/legacy":     "",
		"explicit_zero_numbers_empty_data/cleanup320": "",
		"explicit_zero_numbers_empty_data/cleanup330": "",
		"mpt_max_int64/nil":                           "",
		"mpt_max_int64/small":                         "",
		"mpt_max_int64/legacy":                        "",
		"mpt_max_int64/cleanup320":                    "",
		"mpt_max_int64/cleanup330":                    "",
		"large_mantissas_rounding/nil":                "",
		"large_mantissas_rounding/small":              "",
		"large_mantissas_rounding/legacy":             "",
		"large_mantissas_rounding/cleanup320":         "",
		"large_mantissas_rounding/cleanup330":         "",
		"small_mantissas/nil":                         "",
		"small_mantissas/small":                       "",
		"small_mantissas/legacy":                      "",
		"small_mantissas/cleanup320":                  "",
		"small_mantissas/cleanup330":                  "",
		"negative_numbers/nil":                        "",
		"negative_numbers/small":                      "",
		"negative_numbers/legacy":                     "",
		"negative_numbers/cleanup320":                 "",
		"negative_numbers/cleanup330":                 "",
	}
	for _, c := range vaultGoldenCases() {
		for _, r := range vaultGoldenRules() {
			name := c.name + "/" + r.name
			t.Run(name, func(t *testing.T) {
				data, err := serializeVaultForRules(c.data, r.rules)
				if err != nil {
					t.Fatalf("serializeVaultForRules: %v", err)
				}
				if got := strings.ToUpper(hex.EncodeToString(data)); got != want[name] {
					t.Fatalf("encoding changed\n got: %s\nwant: %s", got, want[name])
				}
			})
		}
	}
}
